package com.example.agendapersonal.avisos;

import android.app.*;import android.content.*;import android.os.*;import android.graphics.*;import android.graphics.drawable.GradientDrawable;import android.view.*;import android.widget.*;import java.util.*;
import com.example.agendapersonal.ui.Iconos;import com.example.agendapersonal.R;

/** Un círculo por categoría; al abrirlo conserva las acciones de consulta y ocultación. */
public class VentanaAvisos extends Service {
 private WindowManager wm;private LinearLayout raiz;private WindowManager.LayoutParams parametros;private String abierta,fecha="";private final Set<String> ocultos=new HashSet<>();
 @Override public IBinder onBind(Intent i){return null;}
 private int dp(float n){return Math.round(n*getResources().getDisplayMetrics().density);}
 private GradientDrawable fondo(int color,float radio){GradientDrawable d=new GradientDrawable();d.setColor(color);d.setCornerRadius(dp(radio));return d;}
 @Override public int onStartCommand(Intent i,int flags,int id){if(i!=null&&"OCULTAR".equals(i.getAction())){getSharedPreferences("agenda_avisos",MODE_PRIVATE).edit().putBoolean("flotante",false).apply();stopSelf();return START_NOT_STICKY;}if(!android.provider.Settings.canDrawOverlays(this)){stopSelf();return START_NOT_STICKY;}ProgramadorAvisos.canales(this);PendingIntent cerrar=PendingIntent.getService(this,0,new Intent(this,VentanaAvisos.class).setAction("OCULTAR"),PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);Notification n=new Notification.Builder(this,ProgramadorAvisos.FLOTANTE).setSmallIcon(R.drawable.ic_aviso_agenda).setContentTitle("Actividades críticas de hoy").setContentText("Tocá el ícono de una categoría para ver sus avisos").setOngoing(true).addAction(new Notification.Action.Builder(null,"Ocultar ventana",cerrar).build()).build();startForeground(84,n);if(raiz==null){wm=getSystemService(WindowManager.class);parametros=new WindowManager.LayoutParams(WindowManager.LayoutParams.WRAP_CONTENT,WindowManager.LayoutParams.WRAP_CONTENT,WindowManager.LayoutParams.TYPE_APPLICATION_OVERLAY,WindowManager.LayoutParams.FLAG_NOT_FOCUSABLE,PixelFormat.TRANSLUCENT);parametros.gravity=Gravity.TOP|Gravity.END;parametros.y=dp(100);raiz=new LinearLayout(this);raiz.setOrientation(LinearLayout.VERTICAL);wm.addView(raiz,parametros);}dibujar();return START_NOT_STICKY;}
 private String categoria(ProgramadorAvisos.Aviso a){String c=a.registro.texto("categoria");return c.isEmpty()?"OTRA":c;}
 private String nombre(String c){switch(c){case "ESTUDIOS":return "Estudios";case "SOCIALES":return "Sociales";case "SALUD":return "Salud";case "TRABAJO":return "Trabajo";case "EJERCICIO":return "Ejercicio";case "FREELANCE":return "Freelance";default:return "Agenda";}}
 private void dibujar(){com.example.agendapersonal.ui.Tema.aplicar(this);String hoy=java.time.LocalDate.now().toString();if(!hoy.equals(fecha)){fecha=hoy;ocultos.clear();}Map<String,List<ProgramadorAvisos.Aviso>> grupos=new LinkedHashMap<>();for(ProgramadorAvisos.Aviso a:ProgramadorAvisos.criticos(this))if(!ocultos.contains(a.clave()))grupos.computeIfAbsent(categoria(a),k->new ArrayList<>()).add(a);if(grupos.isEmpty()){stopSelf();return;}raiz.removeAllViews();if(abierta!=null&&!grupos.containsKey(abierta))abierta=null;
  if(abierta==null){raiz.setPadding(dp(4),dp(4),dp(4),dp(4));raiz.setBackground(null);for(Map.Entry<String,List<ProgramadorAvisos.Aviso>> grupo:grupos.entrySet()){String cat=grupo.getKey();FrameLayout burbuja=new FrameLayout(this);GradientDrawable circulo=fondo(com.example.agendapersonal.ui.Tema.color(this,R.attr.agenda_primary_light),50);circulo.setStroke(dp(1),com.example.agendapersonal.ui.Tema.color(this,R.attr.agenda_border));burbuja.setBackground(circulo);burbuja.setElevation(dp(5));ImageView imagen=new ImageView(this);imagen.setImageResource(Iconos.de(nombre(cat)));imagen.setImportantForAccessibility(View.IMPORTANT_FOR_ACCESSIBILITY_NO);FrameLayout.LayoutParams icono=new FrameLayout.LayoutParams(dp(29),dp(29),Gravity.CENTER);burbuja.addView(imagen,icono);int cantidad=grupo.getValue().size();if(cantidad>1){TextView contador=new TextView(this);contador.setText(cantidad>99?"99+":String.valueOf(cantidad));contador.setTextColor(Color.WHITE);contador.setTextSize(10);contador.setGravity(Gravity.CENTER);contador.setBackground(fondo(com.example.agendapersonal.ui.Tema.color(this,R.attr.agenda_primary),10));contador.setImportantForAccessibility(View.IMPORTANT_FOR_ACCESSIBILITY_NO);FrameLayout.LayoutParams cp=new FrameLayout.LayoutParams(dp(22),dp(20),Gravity.TOP|Gravity.END);burbuja.addView(contador,cp);}LinearLayout.LayoutParams bp=new LinearLayout.LayoutParams(dp(54),dp(54));bp.setMargins(dp(3),dp(3),dp(3),dp(7));raiz.addView(burbuja,bp);burbuja.setContentDescription(nombre(cat)+", "+cantidad+" actividades de hoy. Abrir avisos");burbuja.setOnClickListener(v->{abierta=cat;dibujar();});arrastrable(burbuja);}return;}
  raiz.setPadding(dp(10),dp(10),dp(10),dp(10));GradientDrawable panel=fondo(com.example.agendapersonal.ui.Tema.color(this,R.attr.agenda_surface),22);panel.setStroke(dp(1),com.example.agendapersonal.ui.Tema.color(this,R.attr.agenda_border));raiz.setBackground(panel);int ancho=Math.min(dp(286),getResources().getDisplayMetrics().widthPixels-dp(44));LinearLayout cabecera=new LinearLayout(this);cabecera.setGravity(Gravity.CENTER_VERTICAL);ImageView icono=new ImageView(this);icono.setImageResource(Iconos.de(nombre(abierta)));cabecera.addView(icono,new LinearLayout.LayoutParams(dp(28),dp(28)));TextView titulo=new TextView(this);titulo.setText(nombre(abierta)+" · "+grupos.get(abierta).size());titulo.setTextColor(com.example.agendapersonal.ui.Tema.color(this,R.attr.agenda_text));titulo.setTextSize(17);titulo.setTypeface(null,Typeface.BOLD);titulo.setPadding(dp(8),0,0,0);cabecera.addView(titulo,new LinearLayout.LayoutParams(0,dp(48),1));titulo.setGravity(Gravity.CENTER_VERTICAL);ImageButton contraer=new ImageButton(this);contraer.setImageResource(R.drawable.ic_chevron);contraer.setBackgroundColor(Color.TRANSPARENT);contraer.setContentDescription("Volver a los íconos de categorías");contraer.setOnClickListener(v->{abierta=null;dibujar();});cabecera.addView(contraer,new LinearLayout.LayoutParams(dp(48),dp(48)));raiz.addView(cabecera,new LinearLayout.LayoutParams(ancho,dp(48)));arrastrable(titulo);
  ScrollView scroll=new ScrollView(this);LinearLayout items=new LinearLayout(this);items.setOrientation(LinearLayout.VERTICAL);scroll.addView(items);raiz.addView(scroll,new LinearLayout.LayoutParams(ancho,Math.min(dp(300),dp(116)*grupos.get(abierta).size())));for(ProgramadorAvisos.Aviso a:grupos.get(abierta)){TextView abrir=new TextView(this);abrir.setText(a.registro.texto("descripcion"));abrir.setTextColor(com.example.agendapersonal.ui.Tema.color(this,R.attr.agenda_text));abrir.setTextSize(16);abrir.setTypeface(null,Typeface.BOLD);abrir.setPadding(dp(10),dp(12),dp(10),dp(8));abrir.setMinHeight(dp(48));abrir.setBackground(fondo(com.example.agendapersonal.ui.Tema.color(this,R.attr.agenda_primary_light),12));abrir.setOnClickListener(v->startActivity(a.abrir(this)));abrir.setFocusable(true);items.addView(abrir,new LinearLayout.LayoutParams(-1,-2));TextView ocultar=new TextView(this);ocultar.setText("Ocultar este aviso");ocultar.setTextColor(com.example.agendapersonal.ui.Tema.color(this,R.attr.agenda_primary));ocultar.setGravity(Gravity.END|Gravity.CENTER_VERTICAL);ocultar.setPadding(dp(8),0,dp(8),0);ocultar.setMinHeight(dp(48));ocultar.setOnClickListener(v->{ocultos.add(a.clave());dibujar();});ocultar.setFocusable(true);items.addView(ocultar,new LinearLayout.LayoutParams(-1,dp(48)));}}
 private void arrastrable(View vista){vista.setOnTouchListener(new View.OnTouchListener(){float x,y;int px,py;boolean movio;public boolean onTouch(View v,MotionEvent e){switch(e.getActionMasked()){case MotionEvent.ACTION_DOWN:x=e.getRawX();y=e.getRawY();px=parametros.x;py=parametros.y;movio=false;return true;case MotionEvent.ACTION_MOVE:float dx=e.getRawX()-x,dy=e.getRawY()-y;if(Math.abs(dx)+Math.abs(dy)>dp(8))movio=true;if(movio){parametros.x=Math.max(0,Math.min(getResources().getDisplayMetrics().widthPixels-dp(60),px-(int)dx));parametros.y=Math.max(dp(24),Math.min(getResources().getDisplayMetrics().heightPixels-dp(70),py+(int)dy));wm.updateViewLayout(raiz,parametros);}return true;case MotionEvent.ACTION_UP:if(!movio)v.performClick();return true;default:return true;}}});}
 @Override public void onDestroy(){if(wm!=null&&raiz!=null)wm.removeView(raiz);raiz=null;super.onDestroy();}
}
